#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

int main() {
    int n;
    cin >> n;
    int a[1000];
    int maxVal = 0;
    for (int i = 0; i < n; i++) {
        cin >> a[i];
        if (a[i] > maxVal) maxVal = a[i];
    }
    int bucketCount = 10;
    vector<vector<int>> buckets(bucketCount);
    for (int i = 0; i < n; i++) {
        int idx = a[i] * bucketCount / (maxVal + 1);
        buckets[idx].push_back(a[i]);
    }
    for (int i = 0; i < bucketCount; i++) {
        sort(buckets[i].begin(), buckets[i].end());
    }
    for (int i = 0; i < bucketCount; i++) {
        for (int x : buckets[i]) cout << x << " ";
    }
    return 0;
}

#include <iostream>
using namespace std;

int getMax(int a[], int n) {
    int mx = a[0];
    for (int i = 1; i < n; i++)
        if (a[i] > mx) mx = a[i];
    return mx;
}

void countSort(int a[], int n, int exp) {
    int output[1000];
    int cnt[10] = {0};
    for (int i = 0; i < n; i++) cnt[(a[i] / exp) % 10]++;
    for (int i = 1; i < 10; i++) cnt[i] += cnt[i - 1];
    for (int i = n - 1; i >= 0; i--) {
        output[cnt[(a[i] / exp) % 10] - 1] = a[i];
        cnt[(a[i] / exp) % 10]--;
    }
    for (int i = 0; i < n; i++) a[i] = output[i];
}

int main() {
    int n;
    cin >> n;
    int a[1000];
    for (int i = 0; i < n; i++) cin >> a[i];
    int mx = getMax(a, n);
    for (int exp = 1; mx / exp > 0; exp *= 10)
        countSort(a, n, exp);
    for (int i = 0; i < n; i++) cout << a[i] << " ";
    return 0;
}

